test("after 14:00 Friday skips Saturday Sunday and Monday holiday and delivery is 2 business days after ship", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-03T15:00", transitDays: 2, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-09" });
});
test("before cutoff on a business day ships that day and delivery is 1 business day later with an empty holiday list", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});
test("exactly 14:00 is not before cutoff so ship is the next business day then 1", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});
test("13:59 on a business day is before cutoff and ships that day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T13:59", transitDays: 1, holidays: [] }), { shipDate: "2026-07-01", deliveryDate: "2026-07-02" });
});
test("14:01 is after cutoff and ships the next business day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-01T14:01", transitDays: 1, holidays: [] }), { shipDate: "2026-07-02", deliveryDate: "2026-07-03" });
});
test("Saturday after cutoff ships the next business day only and zero transit days means delivery equals ship", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-04T15:00", transitDays: 0, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-06" });
});
test("Sunday is not a ship day even before 14:00 so ship is Monday then 1 business day", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-05T10:00", transitDays: 1, holidays: [] }), { shipDate: "2026-07-06", deliveryDate: "2026-07-07" });
});
test("a holiday booking day at 13:59 is not a ship day so ship is Tuesday and delivery is Wednesday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-06T13:59", transitDays: 1, holidays: ["2026-07-06"] }), { shipDate: "2026-07-07", deliveryDate: "2026-07-08" });
});
test("holiday the rule needs is first in the list so Friday 25 Dec is skipped and delivery is Monday 28 Dec", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-12-24T09:00", transitDays: 1, holidays: ["2026-12-25", "2026-01-01", "2026-07-04"] }), { shipDate: "2026-12-24", deliveryDate: "2026-12-28" });
});
test("holiday the rule needs is middle and whole number 2.0 ships Friday skips Monday and counts Tuesday then Wednesday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-07-10T10:00", transitDays: 2.0, holidays: ["2026-01-01", "2026-07-13", "2026-12-25"] }), { shipDate: "2026-07-10", deliveryDate: "2026-07-15" });
});
test("holiday the rule needs is last so Thursday ship skips Friday holiday and weekend and counts Monday then Tuesday", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-12-31T13:00", transitDays: 2, holidays: ["2026-07-04", "2026-12-25", "2027-01-01"] }), { shipDate: "2026-12-31", deliveryDate: "2027-01-05" });
});
test("last day of a month ships and 1 business day later is the 1st of the next month", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2026-03-31T10:00", transitDays: 1, holidays: [] }), { shipDate: "2026-03-31", deliveryDate: "2026-04-01" });
});
test("leap day is a Thursday business day and can be the delivery date", function () {
  assert.deepEqual(code.promiseDelivery({ bookedAt: "2024-02-28T09:00", transitDays: 1, holidays: [] }), { shipDate: "2024-02-28", deliveryDate: "2024-02-29" });
});
test("negative transit days throws invalid transitDays", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: -1, holidays: [] });
  }, /invalid transitDays/);
});
test("transit days that are not a whole number throws invalid transitDays", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1.5, holidays: [] });
  }, /invalid transitDays/);
});
test("an input field other than bookedAt transitDays and holidays throws unknown field note", function () {
  assert.throws(function () {
    code.promiseDelivery({ bookedAt: "2026-07-01T09:00", transitDays: 1, holidays: [], note: "x" });
  }, /unknown field: note/);
});
